 if len(cs)>1:
  for c in range(min(cs)+1,max(cs)):
   if grid[r][c]==9:grid[r][c]=3
for c in range(20):
 rs=[r for r,cc in pts if cc==c]
 for a,b in zip(rs,rs[1:]):
